// OmniFlow batch 225 - Action Engine v2 (schemas, preview, idempotency, execution ledger, timeout/retry) + event catalog and webhook outbox.
//
// Run from the WEBSITE repo root (the bot root - the folder that contains OmniFlow-Control-Plane/):
//     node action_engine_outbox_225.mjs
// Needs batch 224 (approvals_snapshots_224.mjs) applied first. Safe to run twice (second run says "already"). Old copies are kept as *.pre_225.bak.
//
// What it does:
//  * Fixes (live today): turning a webhook endpoint off/on was never saved (missing commit); the one-time signing secret never reached
//    the owner (read from the wrong place), so merchants could not verify signatures; an endpoint subscribed to broadcasts could
//    wait forever behind older COD events (shared scan of the 10 oldest rows); a new endpoint was flooded with the workspace's
//    history; a failed action could leave the workflow tick's database transaction broken.
//  * Control Plane: portal_actions.py - every action declares typed args (validated before anything runs), preview / dry_run
//    (risk, permission and approval verdict with zero writes), execution ledger portal_action_runs (written in the same transaction
//    as the effect), idempotency keys (workflow steps, API Idempotency-Key header, approvals) so an action runs exactly once,
//    atomic executor with a statement timeout and a bounded retry for serialization/deadlock errors; failures come back as
//    status=error. New endpoints: POST /api/v1/portal/actions/preview, GET /api/v1/portal/actions/runs.
//    portal_event_catalog.py (new) - the typed list of business events (portal_action_log stays the transactional outbox);
//    GET /api/v1/portal/events/catalog. portal_webhooks.py - subscribe by catalog category (payments, orders, shipping, approvals,
//    handoffs, ...), one cursor per endpoint, dead letters after 5 attempts with one owner notification, bulk replay
//    (POST /webhooks/<id>/deliveries/replay-dead). Existing "all" endpoints are pinned to cod,broadcast so nothing new arrives
//    unasked. portal_workflows.py - action steps pass a per-step idempotency key.
//  * Website: Settings -> "Action log"; Integrations -> categories from the catalog, failed count, "Replay failed".
//  * Tests: tools/cp-testrig/test_actions_v2.py (149 checks incl. a real PostgreSQL run when pgserver is installed) + updated
//    test_actions / test_agents / test_approvals / test_lib / test_webhooks / test_workflows.
//
// Optional CP env (defaults are fine): OF_ACTION_TIMEOUT_MS=8000  OF_ACTION_RETRIES=1  OF_ACTION_RUNS_KEEP_DAYS=30
// No new dependency. Tables/columns are created on first use (portal_action_runs; portal_webhooks.last_log_id;
// portal_webhook_deliveries.dead_at) - existing data is kept.
//
// After running:  cd OmniFlow-Control-Plane && git add -A && git commit -m "batch 225" && git push   then in the website root:
//                 git add -A && git commit -m "batch 225" && git push
import fs from "fs";
import { createRequire } from "module";
const require = createRequire(import.meta.url);
const BACKUP_TAG = ".pre_225.bak";
let applied = 0, already = 0, warnings = 0;
if (!fs.existsSync("OmniFlow-Control-Plane") || !fs.statSync("OmniFlow-Control-Plane").isDirectory()) {
  console.log("X Run this from the website repo root (bot root) - the folder that contains OmniFlow-Control-Plane/. Nothing was written.");
  process.exit(1);
}
if (!fs.existsSync("OmniFlow-Control-Plane/app.py")) {
  console.log("X OmniFlow-Control-Plane/ is empty or not the Control Plane repo (no app.py). On a fresh machine the website clone leaves this folder empty: delete it, then clone the Control Plane repo into it (git clone <CP repo url> OmniFlow-Control-Plane) and run this again. Nothing was written.");
  process.exit(1);
}
function compilePython(pathArg) {
  const { spawnSync } = require("child_process");
  for (const py of ["python3", "python", "py"]) {
    const probe = spawnSync(py, ["--version"], { encoding: "utf8" });
    if (probe.status !== 0) continue;
    const check = spawnSync(py, ["-c", "import sys;sys.exit(0 if sys.version_info[0]>=3 else 1)"], { encoding: "utf8" });
    if (check.status !== 0) continue;
    const result = spawnSync(py, ["-c", "import py_compile,sys;py_compile.compile(sys.argv[1],doraise=True);sys.exit(0)", pathArg], { encoding: "utf8" });
    return result.status === 0;
  }
  console.log("  (python not found - skipped compile guard)");
  return true;
}
function writeNewRepair(repoPath, marker, isCp, content) {
  try {
  let existed = false;
  if (fs.existsSync(repoPath)) {
    if (fs.statSync(repoPath).isDirectory()) {
      let target = repoPath + ".dir_conflict.bak";
      let n = 1;
      while (fs.existsSync(target)) { target = repoPath + ".dir_conflict.bak." + n; n++; }
      fs.renameSync(repoPath, target);
      console.log("! " + repoPath + " was a DIRECTORY on this machine - renamed to " + target + "; writing the real file.");
      warnings++;
    } else existed = true;
  }
  if (!existed) {
    const cut = Math.max(repoPath.lastIndexOf("/"), repoPath.lastIndexOf("\\"));
    if (cut > 0) fs.mkdirSync(repoPath.slice(0, cut), { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
      fs.unlinkSync(repoPath);
      console.log("X " + repoPath + " FAILED to compile - not written");
      warnings++;
      return;
    }
    console.log("+ " + repoPath + " (new file)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already correct)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  fs.writeFileSync(repoPath, content, "utf8");
  if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
    fs.copyFileSync(backup, repoPath);
    console.log("X " + repoPath + " FAILED to compile - old copy restored");
    warnings++;
    return;
  }
  console.log("+ " + repoPath + " (REPAIRED - old copy kept as " + BACKUP_TAG + ")");
  applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED: " + err.message);
    warnings++;
  }
}
function removeFile(repoPath) {
  try {
    if (!fs.existsSync(repoPath)) {
      console.log("= " + repoPath + " (already removed)");
      already++;
      return;
    }
    const backup = repoPath + BACKUP_TAG;
    if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
    fs.unlinkSync(repoPath);
    console.log("- " + repoPath + " (removed - old copy kept as " + BACKUP_TAG + ")");
    applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED to remove: " + err.message);
    warnings++;
  }
}
if (!fs.existsSync("OmniFlow-Control-Plane/portal_snapshots.py") || !fs.readFileSync("OmniFlow-Control-Plane/portal_snapshots.py", "utf8").includes("def before_change(")) {
  console.log("X " + "Batch 224 (approvals_snapshots_224.mjs) is not applied in OmniFlow-Control-Plane - run it first." + " Nothing was written.");
  process.exit(1);
}
if (!fs.existsSync("OmniFlow-Control-Plane/portal_vault.py") || !fs.readFileSync("OmniFlow-Control-Plane/portal_vault.py", "utf8").includes("def seal(")) {
  console.log("X " + "Batch 223 (secrets_vault_223.mjs) is not applied in OmniFlow-Control-Plane - run 223 and 224 first." + " Nothing was written.");
  process.exit(1);
}
if (!fs.existsSync("app/dashboard/(portal)/settings/page.tsx") || !fs.readFileSync("app/dashboard/(portal)/settings/page.tsx", "utf8").includes("<ConfigHistoryCard />")) {
  console.log("X " + "Batch 224 is not applied in the website (settings page) - run approvals_snapshots_224.mjs first." + " Nothing was written.");
  process.exit(1);
}
if (!fs.existsSync("lib/omniflow/portal.ts") || !fs.readFileSync("lib/omniflow/portal.ts", "utf8").includes("export function listConfigSnapshots(")) {
  console.log("X " + "Batch 224 is not applied in the website (portal.ts) - run approvals_snapshots_224.mjs first." + " Nothing was written.");
  process.exit(1);
}
writeNewRepair("omniflow-backend-patch/portal_event_catalog.py", "def public_catalog()", false,
    "\"\"\"Event catalog (\u00a7225): one typed list of the platform's business events.\n\nWhy\n---\n``portal_action_log`` already is the platform's event stream AND its\ntransactional outbox: every business change writes its log row on the\nsame cursor (same transaction) as the change itself, so an event exists\nexactly when the change committed - nothing to dual-write, no extra\nqueue. Consumers read that stream with their own cursor:\n\n* workflows  -> ``portal_workflows.trigger_log_events`` (``last_log_id``)\n* webhooks   -> ``portal_webhooks.deliver_pending_webhooks``\n  (per-endpoint ``last_log_id`` since \u00a7225, retries + dead letters)\n\nWhat was missing was a single, typed NAME list: webhooks hardcoded two\nevents, workflows kept their own strings. This module is that list.\nEvery entry below is written by real code today (verified by the rig's\nAST scan) - no aspirational events.\n\nRules\n-----\n* ``category`` is what a webhook subscribes to (``X-Omniflow-Event``);\n  the exact event name travels as ``action`` in the payload.\n* Adding an event = one entry here. Consumers derive from this module.\n\"\"\"\n\nfrom typing import Any, Dict, List\n\n#: category key -> owner-facing label (webhook subscription groups)\nCATEGORIES: Dict[str, str] = {\n    \"cod\": \"COD confirmations\",\n    \"broadcast\": \"Broadcasts\",\n    \"payments\": \"Payments\",\n    \"orders\": \"Orders & checkout\",\n    \"shipping\": \"Shipping\",\n    \"pipeline\": \"Pipeline\",\n    \"approvals\": \"Approvals\",\n    \"handoffs\": \"Handoffs\",\n    \"feedback\": \"Customer feedback\",\n    \"compliance\": \"Opt-outs\",\n    \"risk\": \"Fraud & risk\",\n}\n\n#: event name (portal_action_log.action) -> metadata\nEVENTS: Dict[str, Dict[str, str]] = {\n    \"cod.confirmed\": {\n        \"category\": \"cod\", \"label\": \"COD order confirmed\",\n        \"description\": \"The customer confirmed a cash-on-delivery order.\"},\n    \"cod.declined\": {\n        \"category\": \"cod\", \"label\": \"COD order declined\",\n        \"description\": \"The customer declined a cash-on-delivery order.\"},\n    \"broadcast.sent\": {\n        \"category\": \"broadcast\", \"label\": \"Broadcast sent\",\n        \"description\": \"A broadcast finished sending.\"},\n    \"payment.gateway_paid\": {\n        \"category\": \"payments\", \"label\": \"Payment received\",\n        \"description\": \"A gateway payment landed on a checkout link.\"},\n    \"checkout.created\": {\n        \"category\": \"orders\", \"label\": \"Checkout link created\",\n        \"description\": \"A checkout link was created for a customer.\"},\n    \"checkout.paid\": {\n        \"category\": \"orders\", \"label\": \"Order marked paid\",\n        \"description\": \"An owner marked a checkout link as paid.\"},\n    \"checkout.cancelled\": {\n        \"category\": \"orders\", \"label\": \"Order cancelled\",\n        \"description\": \"A checkout link was cancelled.\"},\n    \"checkout.shipped\": {\n        \"category\": \"orders\", \"label\": \"Order shipped\",\n        \"description\": \"A checkout link was marked shipped.\"},\n    \"checkout.delivered\": {\n        \"category\": \"orders\", \"label\": \"Order delivered\",\n        \"description\": \"A checkout link was marked delivered.\"},\n    \"checkout.returned\": {\n        \"category\": \"orders\", \"label\": \"Order returned\",\n        \"description\": \"A checkout link was marked returned.\"},\n    \"courier.book\": {\n        \"category\": \"shipping\", \"label\": \"Parcel booked\",\n        \"description\": \"A parcel was booked with a courier.\"},\n    \"courier.book.confirm\": {\n        \"category\": \"shipping\", \"label\": \"Draft booking confirmed\",\n        \"description\": \"A draft courier booking was confirmed.\"},\n    \"pipeline.stage_changed\": {\n        \"category\": \"pipeline\", \"label\": \"Pipeline stage changed\",\n        \"description\": \"A contact moved to another pipeline stage.\"},\n    \"approval.created\": {\n        \"category\": \"approvals\", \"label\": \"Approval requested\",\n        \"description\": \"An AI action is waiting for an owner decision.\"},\n    \"approval.approved\": {\n        \"category\": \"approvals\", \"label\": \"Approval approved\",\n        \"description\": \"An owner approved a pending action.\"},\n    \"approval.rejected\": {\n        \"category\": \"approvals\", \"label\": \"Approval rejected\",\n        \"description\": \"An owner rejected a pending action.\"},\n    \"escalation.opened\": {\n        \"category\": \"handoffs\", \"label\": \"Handoff opened\",\n        \"description\": \"A chat was handed to the team.\"},\n    \"escalation.resolved\": {\n        \"category\": \"handoffs\", \"label\": \"Handoff resolved\",\n        \"description\": \"A handed-off chat was resolved.\"},\n    \"csat.received\": {\n        \"category\": \"feedback\", \"label\": \"CSAT score received\",\n        \"description\": \"A customer answered the satisfaction question.\"},\n    \"compliance.optout\": {\n        \"category\": \"compliance\", \"label\": \"Customer opted out\",\n        \"description\": \"A customer asked to stop receiving messages.\"},\n    \"fraud.flagged\": {\n        \"category\": \"risk\", \"label\": \"Order flagged as risky\",\n        \"description\": \"The fraud check flagged an order.\"},\n}\n\n\ndef known(name: str) -> bool:\n    return str(name or \"\") in EVENTS\n\n\ndef category_of(name: str) -> str:\n    return (EVENTS.get(str(name or \"\")) or {}).get(\"category\", \"\")\n\n\ndef actions_for(categories: List[str]) -> List[str]:\n    \"\"\"Event names covered by a webhook subscription (``all`` = every).\"\"\"\n    wanted = set(categories or [])\n    every = \"all\" in wanted\n    return sorted(name for name, spec in EVENTS.items()\n                  if every or spec[\"category\"] in wanted)\n\n\ndef _workflow_triggers() -> Dict[str, List[str]]:\n    \"\"\"event name -> workflow trigger keys that fire on it (fail-soft).\"\"\"\n    found: Dict[str, List[str]] = {}\n    try:\n        import portal_workflows\n\n        for key, spec in portal_workflows.TRIGGERS.items():\n            for action in spec.get(\"actions\") or []:\n                found.setdefault(action, []).append(key)\n    except Exception:\n        return {}\n    return found\n\n\ndef public_catalog() -> Dict[str, Any]:\n    triggers = _workflow_triggers()\n    events = [{\n        \"type\": name,\n        \"label\": spec[\"label\"],\n        \"description\": spec[\"description\"],\n        \"category\": spec[\"category\"],\n        \"categoryLabel\": CATEGORIES.get(spec[\"category\"], spec[\"category\"]),\n        \"workflowTriggers\": triggers.get(name, []),\n    } for name, spec in sorted(EVENTS.items())]\n    counts: Dict[str, int] = {}\n    for item in events:\n        counts[item[\"category\"]] = counts.get(item[\"category\"], 0) + 1\n    return {\n        \"events\": events,\n        \"categories\": [{\"key\": key, \"label\": label,\n                        \"events\": counts.get(key, 0)}\n                       for key, label in CATEGORIES.items()],\n    }\n");
